  KEY `idx_student_marks_subject_code` (`subject_code`),
  KEY `idx_student_marks_student_status` (`student_id`,`status`),
  KEY `idx_student_marks_subject_status` (`subject_code`,`status`),
  KEY `idx_student_marks_semester_year` (`semester`,`academic_year`),
  KEY `idx_student_marks_locked` (`locked_by_user_id`,`locked_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

